(function(){
'use strict';
const R=window.PEPRules,D=R.DATA,$=id=>document.getElementById(id);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>String(R.round(n));
let state=R.fresh(),dirty=false,toastTimer,sectionObserver,activeSection='personal';
const logo=document.querySelector('.masthead img').src;
function get(path){return path.split('.').reduce((v,k)=>v?.[k],state);}
function set(path,value){const a=path.split('.');let o=state;for(const k of a.slice(0,-1))o=o[k];o[a.at(-1)]=value;dirty=true;}
function field(path,label,type='text',help='',full=false){let id=path.replaceAll('.','-');return `<div class="field${full?' full':''}"><label for="${id}">${label}</label><input id="${id}" data-bind="${path}" type="${type}" value="${esc(get(path))}" ${type==='number'?'min="1" step="1"':''} maxlength="500">${help?`<p class="help">${help}</p>`:''}</div>`;}
function area(path,label,help=''){return `<div class="field full"><label for="${path.replaceAll('.','-')}">${label}</label><textarea id="${path.replaceAll('.','-')}" data-bind="${path}" maxlength="10000">${esc(get(path))}</textarea>${help?`<p class="help">${help}</p>`:''}</div>`;}
function select(path,label,options,help=''){return `<div class="field"><label for="${path.replaceAll('.','-')}">${label}</label><select id="${path.replaceAll('.','-')}" data-bind="${path}">${options.map(([v,l])=>`<option value="${esc(v)}" ${String(get(path))===String(v)?'selected':''}>${esc(l)}</option>`).join('')}</select>${help?`<p class="help">${help}</p>`:''}</div>`;}
function check(path,label){return `<label class="checkline"><input type="checkbox" data-bind="${path}" ${get(path)?'checked':''}><span>${label}</span></label>`;}
function toast(msg){clearTimeout(toastTimer);$('toast').textContent=msg;$('toast').hidden=false;toastTimer=setTimeout(()=>$('toast').hidden=true,6000);}
function personal(){const spec=D.specializations[state.student.specialization];return `<section id="personal"><h2>1. Personal details</h2><p class="intro">Build your proposed 120 EC programme. Required courses and checks adapt to your choices. Use <strong>Export draft PEP</strong> to download your entries as a separate editable file, and <strong>Import draft PEP</strong> to restore them. Typing into this form does not change the HTML file.</p><div class="grid">${field('student.firstName','First name')}${field('student.lastName','Last name')}${field('student.number','Student number')}${select('student.specialization','Specialisation',[['','Select specialisation'],...Object.entries(D.names)])}${spec&&Object.keys(spec.paths).length?select('student.path','Path',[['','Select path'],...Object.keys(spec.paths).map(p=>[p,D.paths[p]])]):''}<div class="field"><label for="cohort">Cohort (start year)</label><input id="cohort" value="2026" readonly></div>${select('student.education','Previous education',[['','Select previous education'],['VU_FW','VU bachelor — Farmaceutische Wetenschappen'],['WO','Other university bachelor'],['HBO','HBO / university of applied sciences diploma']])}${field('student.institution','Previous institution')}${field('student.degree','Degree')}${field('student.graduated','Graduation date','date')}</div></section>`;}
function principles(){
 const codes=R.principleCodes(state),nonVU=['WO','HBO'].includes(state.student.education),record=R.principlesStatementRequired(state);
 return `<section id="principles"><h2>2. Principles courses</h2><p class="help">Students with a VU bachelor Farmaceutische Wetenschappen are not allowed to follow any of the Principles courses. Students with another background should follow both Principles courses. If the admission board deviates from this, this decision should be recorded on the PEP form by the Admissions board. In that case, only the admission board completes the decision field and signature in the downloaded PDF.</p>${state.student.education==='VU_FW'?'<p class="notice">Students with a VU bachelor Farmaceutische Wetenschappen are not allowed to follow any of the Principles courses (0 EC). This requirement is fixed and cannot be adjusted.</p>':!state.student.education?'<p class="help">Select your previous education in Personal details first.</p>':''}${nonVU?`<div class="inset"><p class="help">Both Principles are selected by default for a non-VU Pharmaceutical Sciences background; adjust the selection only if decided by the Admissions board. The specialisation coordinator arranges the signature by the Admissions Board.</p><div class="choices">${D.principles.map(code=>`<label class="choice"><input type="checkbox" data-array="principles.required" value="${code}" ${codes.includes(code)?'checked':''}><span>${esc(R.map[code].name)}<small>${code}</small></span><b>6 EC</b></label>`).join('')}</div>${record?'<h3>Admission board decision (to be filled in by admission board)</h3><p class="help">The Admissions Board records its decision and signs the downloaded PDF because one or both Principles courses have been deselected.</p>':''}</div>`:''}${state.student.education?`<p class="section-subtotal">Principles courses in this plan: ${codes.length*6} EC</p>`:''}</section>`;
}
function courseRows(codes,{editable=true,removable=false}={}){return `<table class="course-table"><thead><tr><th>Course</th><th class="ec">EC</th>${editable||removable?'<th class="actions">Details</th>':''}</tr></thead><tbody>${codes.map(code=>{const c=R.map[code];if(!c)return `<tr><td>Unrecognized code: ${esc(code)}</td><td></td>${editable||removable?`<td><button data-action="remove-elective" data-code="${esc(code)}">Remove</button></td>`:''}</tr>`;const det=state.courseDetails[code],canEdit=editable&&!R.isFixedCourse(state,code);return `<tr><td>${esc(c.name)}<span class="code">${esc(code)} · Level ${c.level}${canEdit&&det?.outside?' · Outside VU':''}</span></td><td class="ec">${c.ec}</td>${editable||removable?`<td class="actions">${canEdit?`<button class="quiet small" data-action="course" data-code="${code}" aria-label="Details for ${esc(c.name)}">Edit</button>`:''}${removable?`<button class="quiet small" data-action="remove-elective" data-code="${code}" aria-label="Remove ${esc(c.name)}">Remove</button>`:''}</td>`:''}</tr>`;}).join('')}</tbody></table>`;}
function compulsory(){if(R.isEducation(state))return `<section id="compulsory"><h2>3. Compulsory courses</h2><h3>DDS component · 12 EC</h3>${courseRows(R.educationSpec().compulsory,{editable:false})}<h3>Education component · 54 EC</h3>${courseRows(R.educationSpec().educationCompulsory,{editable:false})}<p class="help">All listed courses are fixed, including Peergroup 1, Peergroup 2 and Startweek at 0 EC. Exemptions are requested separately; exempted courses remain included.</p></section>`;const codes=R.requiredCodes(state).filter(c=>!D.principles.includes(c));return `<section id="compulsory"><h2>3. Compulsory courses</h2>${codes.length?courseRows(codes,{editable:false}):'<p class="empty">Choose a specialisation to see your compulsory courses.</p>'}<p class="help">These compulsory VU courses and their EC are fixed and cannot be omitted. Exemptions are requested separately; exempted courses remain included with their normal EC.</p></section>`;}
function constrained(){
 if(R.isEducation(state))return `<section id="constrained"><h2>4. Constrained electives</h2><p class="help">Choose one course (6 EC) for the DDS component. <span class="required-mark">* Required choice.</span> The other course may be added under DDS electives if it fits the 60 EC DDS component.</p><div class="choices">${R.educationSpec().constrained.map(code=>`<label class="choice"><input type="radio" name="education-constrained" data-education-constrained value="${code}" ${state.constrained.includes(code)?'checked':''}><span>${esc(R.map[code].name)}<small>${code}</small></span><b>6 EC</b></label>`).join('')}</div><p class="section-subtotal">${state.constrained.length} / 1 course selected · ${state.constrained.length*6} EC</p></section>`;

 const spec=D.specializations[state.student.specialization],required=R.pathCodes(state);
 if(R.needsPath(state))return `<section id="constrained"><h2>4. Constrained electives</h2><p class="notice"><strong>Select your path first.</strong> For ${esc(state.student.specialization)}, the available choices and required courses depend on your path. <a href="#personal">Choose your path in Personal details</a> to continue.</p></section>`;
 return `<section id="constrained"><h2>4. Constrained electives</h2><p class="help">Select two or more courses (min. 12 EC) here. Required path courses are already preselected if applicable.</p>${state.student.path==='MP'?'<p class="help">Molecular Pharmacology requires Drug Target Biochemistry &amp; Signalling. Choose at least one of the other five courses as an additional constrained elective.</p>':''}${spec?`<div class="choices">${spec.constrained.map(code=>`<label class="choice"><input type="checkbox" data-array="constrained" value="${code}" ${state.constrained.includes(code)?'checked':''}><span>${esc(R.map[code].name)}${required.includes(code)?'<span class="tag">Required for path</span>':''}<small>${code}</small></span><b>6 EC</b></label>`).join('')}</div><p class="section-subtotal">${state.constrained.length} courses selected · minimum 2 · ${state.constrained.length*6} EC</p>`:'<p class="empty">Choose a specialisation first.</p>'}</section>`;
}
function majorCourseRows(){
 if(!state.major.route)return '<p class="help">Choose a registration route to see the course(s), codes and EC.</p>';
 const rows=R.components(state).filter(r=>r.section==='Major research project');
 return `<table class="course-table major-course-table"><thead><tr><th>Course</th><th>Course code</th><th class="ec">EC</th></tr></thead><tbody>${rows.map(r=>`<tr data-project="${r.id}"><td>${esc(r.name)}</td><td>${esc(r.code)}</td><td class="ec">${r.ec}</td></tr>`).join('')}</tbody></table>`;
}
function projectFields(key){return `<div class="grid">${select(key+'.hostStatus','Host status',[['','Make selection'],['proposed','Proposed'],['confirmed','Confirmed']])}${select(key+'.topicStatus','Topic status',[['','Make selection'],['unknown','Not yet known'],['proposed','Proposed'],['confirmed','Confirmed']])}${['proposed','confirmed'].includes(state[key].hostStatus)?field(key+'.host','Host / institution'):''}${['proposed','confirmed'].includes(state[key].topicStatus)?area(key+'.topic','Topic'):''}</div>`;}
function projects(){if(R.isEducation(state))return educationProjects();return `<section id="projects"><h2>5. Research projects and literature thesis</h2><p class="help">Specify a proposed or confirmed host for each included project. For the topic, “Not yet known” is allowed. Internship suitability and entry requirements are checked through the existing internship process.</p><h3>Major research project <span class="tag">48 EC · compulsory</span></h3><div class="grid">${select('major.route','Registration route',[['','Choose one route'],['single','Single 48 EC course — year 2 (2027–2028)'],['split','Part 1: 18 EC (2026–2027) + Part 2: 30 EC (2027–2028)']])}<div class="field"><label>Major project total</label><p class="help">${state.major.route?'48 EC for the selected registration route.':'Not counted until a registration route is selected.'}</p></div></div>${majorCourseRows()}<div class="inset">${projectFields('major')}${state.student.path==='SMC'?'<p class="help smc-reminder">For a Synthetic Radiopharmaceutical Chemistry internship, Advanced Radiopharmaceutical Chemistry is required preparation. Discuss this with the internship coordinator.</p>':''}</div><h3>Optional projects</h3>${check('minor.enabled','Include a minor research project <strong>— 30 EC</strong>')}${state.minor.enabled?`<div class="inset"><h4>Minor research project</h4>${projectFields('minor')}<p class="help">Course code: to be announced. Extracurricular internships are not permitted.</p></div>`:''}${check('literature.enabled','Include Literature Thesis DDS <strong>— 12 EC</strong>')}${state.literature.enabled?`<div class="inset"><h4>Literature Thesis DDS · XM_0198</h4>${projectFields('literature')}<p class="help">The literature thesis is independent of the internship and has a different topic.</p><button class="quiet small" data-action="course" data-code="XM_0198">Course details</button></div>`:''}${state.minor.enabled&&state.literature.enabled?'<p class="notice warning-text"><strong>Strongly discouraged:</strong> combining a major research project, minor research project and literature thesis cannot be completed within the two-year programme and will result in study delay, even when the EC total fits.</p>':''}<details class="help" style="margin-top:16px"><summary>Entry and supervision reminders</summary><p>TER Article 8.1 requires at least 18 EC should be obtained from the programme to be able to start with a major or minor research project or a literature thesis. Major Part 1 must be passed before Part 2. This form does not check results, internship suitability or scheduling.</p></details></section>`;}
function educationProjects(){return `<section id="projects"><h2>5. Major research project</h2><h3>Major research project <span class="tag">30 EC · compulsory · DDS</span></h3>${courseRows(['XM_0200'],{editable:false})}<div class="inset">${projectFields('major')}</div><p class="help">Minor research projects and literature theses are not available for the Education specialisation.</p>${state.minor.enabled?'<p class="notice warning-text">This imported plan contains a minor, which must be removed.</p><button data-action="remove-education-minor">Remove minor research project</button>':''}<details class="help"><summary>Entry and language reminders</summary><p>At least 18 EC must be obtained from the programme before starting the major research project (TER Article 8.1). The Education specialisation is taught in English in year 1 and Dutch in year 2; Dutch-language admission requirements apply. Entry eligibility is checked through the existing admission and internship processes.</p></details></section>`;}
function picker(category){const spec=D.specializations[state.student.specialization];const excluded=new Set([...R.requiredCodes(state),...state.constrained,...(R.isEducation(state)?[]:(spec?.constrained||[])),...state.electives,'XM_0198',...D.principles,'XM_0196']);const available=D.courses.filter(c=>c.category===category&&!excluded.has(c.code)&&(!R.isEducation(state)||R.availableDDS(state).includes(c.code))).sort((a,b)=>a.name.localeCompare(b.name));return `<div class="selector"><div class="field"><label for="picker-${category}">Add ${category==='alpha'?'an alpha/gamma':'a general'} elective</label><select id="picker-${category}"><option value="">Choose a course</option>${available.map(c=>`<option value="${c.code}">${esc(c.name)} · ${c.ec} EC</option>`).join('')}</select></div><button data-action="add-elective" data-category="${category}">Add course</button></div>`;}
function customRows(rows=state.custom){return rows.length?`<table class="course-table"><thead><tr><th>Unlisted course</th><th class="ec">EC</th><th class="actions">Details</th></tr></thead><tbody>${rows.map(c=>`<tr><td>${esc(c.name)||'Untitled course'}<span class="tag">${R.isEducation(state)?c.component==='education'?'Education':c.component==='dds'?'DDS':'Choose component':c.category==='alpha'?'Alpha/gamma':c.category==='general'?'General':'Choose category'}</span><span class="code">${esc(c.institution)} · ${esc(c.code)||'Course code required'} · Level ${esc(c.level)||'required'}</span></td><td class="ec">${esc(c.ec)||'—'}</td><td class="actions"><button class="quiet small" data-action="edit-custom" data-id="${esc(c.uid)}">Edit</button><button class="quiet small" data-action="remove-custom" data-id="${esc(c.uid)}">Remove</button></td></tr>`).join('')}</tbody></table>`:'<p class="empty">No unlisted courses added.</p>';}
function educationUnlisted(component){const label=component==='dds'?'DDS':'Education';return `<button data-action="add-custom" data-component="${component}">Add an unlisted course</button><p class="help">Unlisted ${label} courses require individual Examination Board approval.${component==='dds'?' Alpha/gamma courses are not allowed in the DDS component.':''}</p>${customRows(state.custom.filter(c=>c.component===component))}`;}
function educationElectives(){return `<section id="electives"><h2>6. Other elective courses</h2><p class="notice">Required split: 60 EC DDS + 60 EC Education. Extra credits need justification and approval. Alpha/gamma courses are not allowed in the DDS component.</p><div id="dds-elective-space"><h3>DDS electives · year 1</h3><p class="help">Use the remaining DDS space after Principles, the compulsory DDS courses, the 30 EC major and the 6 EC constrained choice. The unchosen constrained course is also available here.</p>${state.electives.length?courseRows(state.electives,{removable:true}):'<p class="empty">No DDS electives selected.</p>'}${picker('general')}${educationUnlisted('dds')}</div><div id="education-elective-space"><h3>Education electives · year 2 <span class="tag">6 EC required</span></h3><p class="help">Choose Praktijkonderzoek (6 EC) or two distinct 3 EC courses. <span class="required-mark">* Required elective space.</span> Wereldburgerschap and Wereldburgerschap deel 2 must be taken together. An unlisted Education course needs individual Examination Board approval.</p><div class="choices">${R.educationSpec().educationElectives.map(code=>`<label class="choice"><input type="checkbox" data-array="educationElectives" value="${code}" ${state.educationElectives.includes(code)?'checked':''}><span>${esc(R.map[code].name)}<small>${code}</small></span><b>${R.map[code].ec} EC</b></label>`).join('')}</div>${educationUnlisted('education')}${state.educationElectives.filter(c=>!R.educationSpec().educationElectives.includes(c)).map(c=>`<p class="warning-text">Unavailable Education elective: ${esc(R.map[c]?.name||c)} <button data-action="remove-education-elective" data-code="${esc(c)}">Remove</button></p>`).join('')}</div>${state.custom.some(c=>!['dds','education'].includes(c.component))?`<div class="notice"><h3>Unlisted courses needing a component</h3><p>Choose DDS or Education using Edit to place each imported course in the correct elective space.</p>${customRows(state.custom.filter(c=>!['dds','education'].includes(c.component)))}</div>`:''}</section>`;}
function electives(){if(R.isEducation(state))return educationElectives();const general=state.electives.filter(c=>R.map[c]?.category!=='alpha'),alpha=state.electives.filter(c=>R.map[c]?.category==='alpha');return `<section id="electives"><h2>6. Other elective courses</h2><p class="help">Elective courses except your own constrained electives are available here. If your preferred course is not available you can add it using the &quot;Add an unlisted course&quot; button below.</p><h3>General electives</h3>${general.length?courseRows(general,{removable:true}):'<p class="empty">No general electives selected.</p>'}${picker('general')}${state.electives.includes('XM_0197')?'<p class="help">Didactics of Science Supervision: enrol in the same academic year as your supervision activities and plan the theoretical preparation in advance (period 1 or 3).</p>':''}<h3>Alpha/gamma electives <span class="tag">Maximum 18 EC</span></h3><p class="help">Society, communication and related electives. Common courses can be chosen from the drop-down menu. If you prefer another alpha/gamma course, you can add it through the &quot;Add an unlisted course&quot; button below.</p>${alpha.length?courseRows(alpha,{removable:true}):'<p class="empty">No alpha/gamma electives selected.</p>'}${picker('alpha')}${state.educationElectives.length?`<h3>Education selections from another specialisation</h3><p class="notice warning-text">These selections are not available for this specialisation.</p>${state.educationElectives.map(c=>`<p>${esc(R.map[c]?.name||c)} <button data-action="remove-education-elective" data-code="${esc(c)}">Remove</button></p>`).join('')}`:''}<h3>Courses outside this catalogue</h3><p class="help">Complete all course details and choose the elective course type &quot;General&quot; or &quot;Alpha/gamma&quot;. The course will be assessed as part of the PEP review.</p>${customRows()}<button data-action="add-custom">Add an unlisted course</button></section>`;}
function submissionInstructions(){return `<p class="help approval-instructions">After downloading the completed PDF, send it to your specialisation coordinator for completion and preapproval. Once you get the signed PEP form back from your specialisation coordinator, you should submit it to the DDS examination board for approval via:<br><a href="https://vu.nl/en/student/elective-space/electives" target="_blank" rel="noopener noreferrer">https://vu.nl/en/student/elective-space/electives</a></p>`;}
function reviewShell(){return `<section id="review"><h2>7. Review and Generate PDF for approval</h2><div id="review-results"></div><div class="grid" style="margin-top:24px"><div class="field"><label for="coordinator">Specialisation coordinator</label><input id="coordinator" value="${esc(R.coordinatorName(state))}" readonly placeholder="Select a specialisation">${R.isEducation(state)?'<p class="help">d.p.geerke@vu.nl · preapproves both the DDS and Education components.</p>':''}</div>${area('notes','Additional explanation (optional)')}<p id="exception-help" class="help full" hidden>Exception requests should use the relevant “Request exception” button above so the affected rule is clear.</p></div><div class="exports"><button id="download-pdf" class="primary" aria-describedby="pdf-availability">Download PDF for approval</button><button id="export-draft-bottom" data-action="export-draft"><svg class="action-icon" aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M9 3H4v18h14v-5 M13 3h8v8 M21 3l-11 11"/></svg><span class="button-label">Export draft PEP</span></button><button id="open-draft-bottom" data-action="open-draft"><svg class="action-icon" aria-hidden="true" focusable="false" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round"><path d="M3 7V4h6l2 3h10v3 M3 7v14h16l3-11H7L3 21"/></svg><span class="button-label">Import draft PEP</span></button></div><p id="pdf-availability" class="pdf-availability" role="status" aria-live="polite"></p><details class="draft-help"><summary>How to use import and export functions</summary><p><strong>Export draft PEP</strong> saves your entries as a JSON file. <strong>Import draft PEP</strong> imports the draft PEP so you can continue editing later on. An exported curriculum planning generated with the <a href="https://dannyscholten.github.io/dds-curriculum-planner/" target="_blank" rel="noopener noreferrer">DDS curriculum planner</a> can also be imported via this button. Use <strong>Export for PEP approval</strong> in the curriculum planner.</p><p><strong>Note:</strong> Changes to this form are not saved automatically.</p><p><strong>Note:</strong> PDFs can be generated, but not be imported by this tool.</p></details>${submissionInstructions()}</section>`;}
const requiredMark='<span class="required-mark" aria-hidden="true"> *</span>';
const requiredNote='<p class="mandatory-note"><span class="required-mark" aria-hidden="true">*</span> Indicates a mandatory field.</p>';
function mandatory(path){
 if(['student.firstName','student.lastName','student.number','student.specialization','student.path','student.education','student.institution','student.degree','student.graduated','major.route','literature.code'].includes(path))return true;
 if(/^(major|minor|literature)\.(hostStatus|topicStatus)$/.test(path))return true;
 const match=/^(major|minor|literature)\.(host|topic)$/.exec(path);return !!match&&['proposed','confirmed'].includes(state[match[1]][match[2]+'Status']);
}
function markField(el,needed){
 el.required=needed;el.setAttribute('aria-required',String(needed));const label=el.id?document.querySelector('label[for="'+el.id+'"]'):null;if(!label)return;
 label.querySelectorAll('.required-mark').forEach(e=>e.remove());label.innerHTML=label.innerHTML.replace(/\s*\*\s*$/,'');if(needed)label.insertAdjacentHTML('beforeend',requiredMark);
}
function markRequired(){
 document.querySelectorAll('#main-content [data-bind]').forEach(el=>{if(el.type!=='checkbox')markField(el,mandatory(el.dataset.bind));});
 for(const id of ['cohort','coordinator'])markField($(id),true);
 document.querySelectorAll('#main-content>section').forEach(el=>el.insertAdjacentHTML('beforeend',requiredNote));
 if($('constrained').querySelector('.choices')&&!R.isEducation(state)){$('constrained').querySelector('.choices').insertAdjacentHTML('beforebegin','<p class="selection-label"><strong>Minimum of two constrained electives'+requiredMark+'</strong></p>');}
}
function markDialog(){
 const outside=$('editor').querySelector('[name="outside"]');
 $('editor').querySelectorAll('input[id],select[id],textarea[id]').forEach(el=>{if(el.type==='checkbox')return;const conditional=outside&&['institution','url'].includes(el.name);markField(el,conditional?outside.checked:el.required);});
}
function render(){state.coordinator=R.coordinatorName(state);R.clearFixedCourseDetails(state);const y=window.scrollY;$('main-content').innerHTML=personal()+principles()+compulsory()+constrained()+projects()+electives()+reviewShell();markRequired();update();observeSections();window.scrollTo(0,y);}
function highlightSection(id){
 activeSection=id;
 document.querySelectorAll('.section-links a').forEach(a=>{const active=a.hash==='#'+id;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});
}
function observeSections(){
 sectionObserver?.disconnect();
 sectionObserver=new IntersectionObserver(entries=>{const visible=entries.filter(e=>e.isIntersecting).sort((a,b)=>Math.abs(a.boundingClientRect.top-110)-Math.abs(b.boundingClientRect.top-110));if(visible.length)highlightSection(visible[0].target.id);},{rootMargin:'-100px 0px -65% 0px',threshold:0});
 document.querySelectorAll('#main-content>section').forEach(e=>sectionObserver.observe(e));highlightSection(activeSection);
}
window.matchMedia('(max-width:850px)').addEventListener('change',e=>{const nav=document.querySelector('.section-nav');if(nav)nav.open=!e.matches;});
function update(){const v=R.evaluate(state);$('summary').innerHTML=`<h2>Total credit count of PEP</h2><div class="total">${fmt(v.total)} <small>/ 120 EC</small></div><div class="meter"><span style="width:${Math.min(100,v.total/120*100)}%;${v.total>120?'background:#a82525':''}"></span></div><p class="remaining">${v.total<120?fmt(120-v.total)+' EC remaining':v.total>120?fmt(v.total-120)+' EC above 120':'Credit total complete'}</p><div class="status-line ${v.errors.length?'error':v.review.length?'review':'pass'}">${v.errors.length?v.errors.length+' item'+(v.errors.length===1?'':'s')+' to complete':v.review.length?v.review.length+' decision / verification item'+(v.review.length===1?'':'s'):'Ready for coordinator review'}</div><div class="aside-details">${['Principles courses','Compulsory courses','Constrained electives','Major research project','Minor research project','Literature thesis','General electives','Alpha/gamma electives','Education compulsory courses','Education electives','Electives awaiting classification'].map(label=>{let n=v.rows.filter(r=>r.section===label).reduce((a,r)=>a+r.ec,0);return n?`<div class="subtotal"><span>${R.isEducation(state)&&label==='General electives'?'DDS electives':label}</span><strong>${fmt(n)}</strong></div>`:''}).join('')}${R.isEducation(state)?`<div class="component-totals"><div class="subtotal"><span>DDS component</span><strong>${fmt(v.ddsTotal)} / 60 EC</strong></div><div class="subtotal"><span>Education component</span><strong>${fmt(v.educationTotal)} / 60 EC</strong></div></div><p class="help">No alpha/gamma courses in the DDS component.</p>`:`<p class="help">Alpha/gamma: ${fmt(v.alpha)} / 18 EC${v.unclassified?' · '+fmt(v.unclassified)+' EC unclassified':''}</p>`}</div><nav aria-label="Sections of this PEP"><details class="section-nav" ${window.matchMedia('(min-width:851px)').matches?'open':''}><summary><h3>Sections of this PEP</h3></summary><div class="section-links"><a href="#personal">1. Personal details</a><a href="#principles">2. Principles courses</a><a href="#compulsory">3. Compulsory courses</a><a href="#constrained">4. Constrained electives</a><a href="#projects">5. ${R.isEducation(state)?'Major research project':'Research projects and literature thesis'}</a><a href="#electives">6. Other elective courses</a><a href="#review">7. Review and Generate PDF for approval</a></div></details></nav>`;
 $('review-results').innerHTML=`<p class="status-line ${v.errors.length?'error':v.review.length?'review':'pass'}">${esc(v.status)}</p><table class="checks"><thead><tr><th>Check</th><th>Status</th></tr></thead><tbody>${v.checks.map(c=>`<tr data-status="${c.status}"><td><strong class="check-title">${esc(c.label)}</strong><br><span class="help">${esc(c.description)}</span><br><strong class="check-value">${esc(c.value)}</strong></td><td class="${c.status==='pass'?'good':c.status==='error'?'bad':'pending'}">${c.status==='pass'?'Passed':c.status==='error'?'Action needed':'Decision required'}</td></tr>`).join('')}</tbody></table>${v.issues.length?['error','review','warning'].filter(severity=>v.issues.some(i=>i.severity===severity)).map(severity=>`<h3>${severity==='error'?'Items to complete':severity==='review'?'Items requiring review':'Planning warnings'}</h3><ul class="review-list">${v.issues.filter(i=>i.severity===severity).map(i=>`<li><span class="issue-type ${i.severity}">${i.severity==='error'?'Action needed':i.severity==='review'?'Decision / verification required':'Planning warning'}</span><p class="issue-message ${i.severity==='warning'||i.severity==='error'?'warning-text':''}">${esc(i.message)}</p>${i.requested?`<p class="issue-message exception-justification"><strong>Exception requested:</strong> ${esc(i.reason)}</p>${i.reference?`<p class="help">Reference: ${esc(i.reference)}</p>`:''}`:''}<div class="issue-actions"><a href="#${i.section}" class="help">Go to section</a>${i.exceptionable?`<button class="quiet small" data-action="exception" data-id="${esc(i.id)}">${i.requested?'Edit exception request':'Request exception'}</button>`:''}</div></li>`).join('')}</ul>`).join(''):'<p class="help">No automatic composition issues found. Coordinator preapproval and Examination Board approval are still required.</p>'}${v.inactiveRequests.length?`<p class="help">${v.inactiveRequests.length} saved exception request(s) no longer apply to the current selections and will not appear as active requests in the PDF.</p>`:''}`;
 const exceptionHelp=$('exception-help');if(exceptionHelp)exceptionHelp.hidden=!v.issues.some(i=>i.exceptionable);
 for(const id of ['download-pdf']){const btn=$(id);if(btn)btn.disabled=!v.canExport;}
 const availability=$('pdf-availability');availability.hidden=!v.canExport;availability.classList.toggle('unavailable',!v.canExport);availability.textContent=v.canExport?(v.review.length?'Available for download. Decision / verification items in the PDF still require review and preapproval.':'Available for download. Send the PDF to your specialisation coordinator for preapproval.'):'Not yet available: complete the '+v.errors.length+' item'+(v.errors.length===1?'':'s')+' listed under “Items to complete” above. Fill in required details and resolve blocking checks, or add a justified exception where offered.';
 $('download-pdf').title=availability.textContent;
 highlightSection(activeSection);document.querySelector('.save-note').textContent=dirty?'Unsaved changes — use Export draft PEP':'Changes are not saved automatically';
}
function dialogFields(name,label,value,type='text',extra=''){return `<div class="field"><label for="dlg-${name}">${label}</label><input id="dlg-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}></div>`;}
function dialogSelect(name,label,value,options,extra=''){return `<div class="field"><label for="dlg-${name}">${label}</label><select id="dlg-${name}" name="${name}" ${extra}>${options.map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
function showDialog(title,body,onSave){$('editor').innerHTML=`<button class="quiet close" type="button" id="dlg-close" aria-label="Close dialog">Close</button><h2 id="dialog-title">${esc(title)}</h2><form id="dialog-form">${body}${requiredNote}<div class="buttons"><button type="button" id="dlg-cancel">Cancel</button><button class="primary" type="submit">Save</button></div></form>`;$('dlg-close').onclick=$('dlg-cancel').onclick=()=>$('editor').close();$('dialog-form').onsubmit=e=>{e.preventDefault();onSave(new FormData(e.target));dirty=true;$('editor').close();render();};markDialog();$('dialog-form').onchange=()=>markDialog();$('editor').showModal();}
function courseDialog(code){
 const c=R.map[code],det=state.courseDetails[code]||{outside:false,institution:'',url:''};if(!c||R.isFixedCourse(state,code))return;
 showDialog(c.name,`<p class="help">${code} · ${c.ec} EC · level ${c.level}. Credit values cannot be edited.</p><p class="help">Exemptions are requested separately. Keep exempted courses in your PEP at their normal EC.</p><label class="checkline"><input type="checkbox" name="outside" ${det.outside?'checked':''}><span>This course is taken at an institution outside VU</span></label><div class="grid">${dialogFields('institution','Institution, if outside VU',det.institution||'')}${dialogFields('url','Public syllabus / course-information link',det.url||'','url')}</div>`,f=>{
  state.courseDetails[code]={outside:f.has('outside'),institution:clean(f.get('institution')),url:clean(f.get('url'))};
 });
}
const clean=v=>String(v??'').trim();
function customDialog(uid,component=''){
 const old=state.custom.find(c=>c.uid===uid),c=old||{uid:'C'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),name:'',code:'',institution:'',ec:'',level:'',category:'',component,url:''};
 showDialog(old?'Edit unlisted course':'Add an unlisted course',`<p class="help">All seven fields are required.</p><div class="grid">${dialogFields('name','Course title *',c.name,'text','required maxlength="500"')}${dialogFields('institution','Institution *',c.institution,'text','required maxlength="500"')}${dialogFields('code','Course code *',c.code,'text','required maxlength="100"')}${dialogFields('ec','EC *',c.ec,'number','required min="0.01" max="120" step="0.01"')}${dialogFields('level','Academic level *',c.level,'text','required maxlength="80" list="academic-levels" placeholder="e.g. 400, 500, 600 or equivalent"')}<datalist id="academic-levels"><option value="400"><option value="500"><option value="600"></datalist>${R.isEducation(state)?dialogSelect('component','PEP component *',c.component||'',[['','Choose DDS or Education'],['dds','DDS — scientific course; no alpha/gamma'],['education','Education']],'required'):dialogSelect('category','Elective category *',c.category,[['','Choose a category'],['general','General elective'],['alpha','Alpha/gamma elective']],'required')}<div class="full">${dialogFields('url','Public syllabus URL *',c.url,'url','required pattern="[hH][tT][tT][pP][sS]?://.+"')}</div></div><p class="help" style="margin-top:12px">Course suitability, overlap and classification are assessed during PEP review. Select existing catalogue courses from the list.</p>`,f=>{
  const updated={uid:c.uid};for(const key of ['name','institution','code','ec','level','category','url'])updated[key]=clean(f.get(key));
  if(R.isEducation(state)){updated.component=clean(f.get('component'));updated.category=updated.component==='education'?'education':'general';}
  state.custom=state.custom.filter(x=>x.uid!==c.uid);state.custom.push(updated);
 });
}
function exceptionDialog(id){const issue=R.evaluate(state).issues.find(i=>i.id===id);if(!issue?.exceptionable)return;const ex=state.exceptions[id]||{};showDialog('Request an exception',`<p>${esc(issue.message)}</p><p class="help">This request will appear in the PDF as “decision required”.</p>${ex.reason?'<button type="button" class="quiet danger" id="remove-exception">Remove exception request</button>':''}<div class="field" style="margin-top:16px"><label for="dlg-reason">Justification</label><textarea id="dlg-reason" name="reason" maxlength="10000" required>${esc(ex.reason||'')}</textarea><p class="help">Explain why the departure is necessary. A justification is mandatory for an exception request.</p></div><div style="margin-top:14px">${dialogFields('reference','Supporting reference, if available',ex.reference||'')}</div>`,f=>{const reason=clean(f.get('reason'));if(reason)state.exceptions[id]={reason,reference:clean(f.get('reference'))};else delete state.exceptions[id];});if($('remove-exception'))$('remove-exception').onclick=()=>{delete state.exceptions[id];dirty=true;$('editor').close();render();};}
function download(name,text,type='application/json'){const blob=new Blob([text],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
function filename(){return 'DDS_PEP_'+(state.student.number||'draft').replace(/[^a-zA-Z0-9_-]/g,'_')+'_'+new Date().toLocaleDateString('en-CA',{timeZone:'Europe/Amsterdam'});}
function saveDraft(){const saved=R.exportDraft(state);download(filename()+'.json',JSON.stringify(saved,null,2));dirty=false;update();toast('Your entries were saved to a separate JSON draft file. Use Import draft PEP to restore them later.');}
async function openFile(file){if(!file)return;if(file.size>2*1024*1024){toast('This file is too large to be a PEP draft (maximum 2 MB).');return;}try{const imported=R.importDraft(JSON.parse(await file.text()));if(dirty&&!confirm('Opening a draft will replace your unsaved changes. Continue?'))return;state=imported;dirty=false;render();$('student-firstName').focus();toast('Draft imported. All checks have been recalculated.');}catch(e){toast('Could not open draft: '+e.message);}finally{$('file-input').value='';}}
function action(e){const b=e.target.closest('[data-action]');if(!b)return;e.preventDefault();const {action,code,id,category}=b.dataset;
 if(action==='remove-education-minor'){state.minor.enabled=false;dirty=true;render();}
 if(action==='course')courseDialog(code);
 if(action==='add-elective'){const selected=$('picker-'+category).value;if(selected){state.electives.push(selected);dirty=true;render();}}
 if(action==='remove-education-elective'){state.educationElectives=state.educationElectives.filter(c=>c!==code);dirty=true;render();}
 if(action==='remove-elective'){state.electives=state.electives.filter(c=>c!==code);dirty=true;render();}
 if(action==='add-custom')customDialog(undefined,b.dataset.component||'');
 if(action==='edit-custom')customDialog(id);
 if(action==='remove-custom'){if(confirm('Remove this unlisted course?')){state.custom=state.custom.filter(c=>c.uid!==id);dirty=true;render();}}
 if(action==='exception')exceptionDialog(id);
}
function changed(e){
 const el=e.target;
 if(el.hasAttribute('data-education-constrained')){state.constrained=[el.value];state.electives=state.electives.filter(c=>c!==el.value);dirty=true;render();return;}
 if(el.dataset.array){
  const path=el.dataset.array,list=get(path);
  if(path==='constrained'&&R.needsPath(state)){el.checked=false;toast('Choose your path in Personal details before selecting constrained electives.');return;}
  if(path==='principles.required')state.principles.override=true;
  set(path,el.checked?[...list,el.value]:list.filter(c=>c!==el.value));
  if(path==='educationElectives'&&['O_MWRLDBS_1','O_MWRLDBS_2'].includes(el.value)){state.educationElectives=state.educationElectives.filter(c=>!['O_MWRLDBS_1','O_MWRLDBS_2'].includes(c));if(el.checked)state.educationElectives.push('O_MWRLDBS_1','O_MWRLDBS_2');}
  if(path==='constrained'&&el.checked)state.electives=state.electives.filter(c=>c!==el.value);
  render();return;
 }
 const path=el.dataset.bind;if(!path)return;
 if(el.tagName==='INPUT'&&el.type!=='checkbox'||el.tagName==='TEXTAREA')return;
 const value=el.type==='checkbox'?el.checked:el.value;
 if(path==='student.specialization'){
  if(state.student.specialization&&value!==state.student.specialization&&!confirm('Changing specialisation updates the compulsory courses. Your current elective choices will be retained where applicable. Education has a fixed 30 EC major and does not allow a minor; switching to Education removes the minor and literature thesis from the plan. Other unavailable choices will need correction. Continue?')){el.value=state.student.specialization;return;}
  const pool=[...new Set([...state.constrained,...state.electives])];set(path,value);state.student.path='';state.constrained=[];
  state.electives=pool.filter(c=>!R.requiredCodes(state).includes(c));R.organiseConstrained(state);
  if(R.isEducation(state)){state.major.route='';state.minor.enabled=false;state.literature={...R.fresh().literature};}
 }else if(path==='student.path'){R.selectPath(state,value);dirty=true;}
 else if(path==='student.education'){
  const previous=state.student.education;set(path,value);
  if(value==='VU_FW'){state.student.institution='Vrije Universiteit Amsterdam';state.student.degree='Farmaceutische Wetenschappen';}else if(previous==='VU_FW'){state.student.institution='';state.student.degree='';}
  state.principles={override:['WO','HBO'].includes(value),required:['WO','HBO'].includes(value)?[...D.principles]:[]};
 }
 else set(path,value);
 render();const focus=document.getElementById(el.id);if(focus)focus.focus({preventScroll:true});
}
function inputted(e){const el=e.target;if(!el.dataset.bind||el.type==='checkbox'||el.tagName==='SELECT')return;set(el.dataset.bind,el.type==='number'?Number(el.value):el.value);update();}
function printCourseTable(rows){return `<table class="print-table"><thead><tr><th>Course / component</th><th class="code">Course code</th><th class="ec">EC</th></tr></thead><tbody>${rows.map(r=>{const detail=R.isFixedCourse(state,r.id)?undefined:state.courseDetails[r.id],bits=[];if(r.custom){bits.push('Institution: '+r.institution+' · Level: '+r.level);bits.push(R.isEducation(state)?'Component: '+(r.component==='education'?'Education':'DDS'):'Category: '+(r.category==='alpha'?'Alpha/gamma':r.category==='general'?'General':'Not supplied'));if(r.url)bits.push(r.url);}if(detail?.outside){bits.push('Outside VU: '+detail.institution);bits.push(detail.url);}return `<tr><td>${esc(r.name)}${bits.length?'<br><small>'+bits.map(esc).join('<br>')+'</small>':''}</td><td>${esc(r.code)}</td><td class="ec">${fmt(r.ec)}</td></tr>`;}).join('')}</tbody></table>`;}
function printProject(key,label){const p=state[key],detail=field=>p[field+'Status']==='unknown'?'Not yet known':!p[field+'Status']?'Not selected':p[field]+' ('+p[field+'Status']+')';return `<div class="print-project"><p><strong>${esc(label)}</strong></p><table class="print-table"><tbody><tr><td class="label">Host</td><td>${esc(detail('host'))}</td></tr><tr><td class="label">Topic</td><td>${esc(detail('topic'))}</td></tr></tbody></table></div>`;}
function resourceLinks(){return `<p class="resource-links"><a href="${D.links.studyGuide}" target="_blank" rel="noopener noreferrer">VU Study Guide — TER</a><span> · </span><a href="${D.links.canvas}" target="_blank" rel="noopener noreferrer">DDS Canvas community</a></p>`;}
function preparePrint(mode){const v=R.evaluate(state);const draft=mode==='draft'||!v.canExport;const time=new Date().toLocaleDateString('en-GB',{timeZone:'Europe/Amsterdam',day:'numeric',month:'long',year:'numeric'});let sections='';
 const info=[['First name',state.student.firstName],['Last name',state.student.lastName],['Student number',state.student.number],['Specialisation',D.names[state.student.specialization]||'Not selected'],...(state.student.path?[['Path',D.paths[state.student.path]||state.student.path]]:[]),['Cohort','2026'],['Previous education',(state.student.education==='VU_FW'?'VU bachelor Farmaceutische Wetenschappen':state.student.education==='HBO'?'HBO diploma':'University bachelor')+' — '+state.student.institution+'; '+state.student.degree+'; graduation '+state.student.graduated]];
 sections+=`<section class="print-section"><h2>1. Personal details</h2><table class="print-table"><tbody>${info.map(([a,b])=>`<tr><td class="label">${esc(a)}</td><td>${esc(b)||'Not supplied'}</td></tr>`).join('')}</tbody></table></section>`;
 if(state.student.education!=='VU_FW')sections+=`<section class="print-section"><h2>2. Principles courses</h2>${v.principles.length?printCourseTable(v.rows.filter(r=>r.section==='Principles courses')):'<p>'+(state.student.education?'Neither Principles course included (0 EC).':'Previous education not selected.')+'</p>'}${v.principlesStatementRequired?`<div class="print-decision" data-pdf-field="admissions_decision"><p><strong>Admission board decision (to be filled in by admission board)${requiredMark}</strong></p><p>To be completed by the admission board in this PDF.</p></div><p class="print-checks mandatory-note">* Mandatory for the admission board.</p>`:state.student.education==='VU_FW'?'<p>Students with a VU bachelor Farmaceutische Wetenschappen are not allowed to follow any of the Principles courses.</p>':v.principles.length===2?'<p>Both Principles courses are included. No Admissions Board decision or signature is required.</p>':''}</section>`;
 sections+=`<section class="print-section"><h2>3. Compulsory courses</h2>${printCourseTable(v.rows.filter(r=>r.section==='Compulsory courses'&&!D.principles.includes(r.code)))}${R.isEducation(state)?`<h3>Education compulsory courses · 54 EC</h3>${printCourseTable(v.rows.filter(r=>r.section==='Education compulsory courses'))}`:''}</section>`;
 sections+=`<section class="print-section"><h2>4. Constrained electives</h2>${printCourseTable(v.rows.filter(r=>r.section==='Constrained electives'))}<p>${R.isEducation(state)?'Choose one of the two courses (6 EC); the other may use DDS elective space.':'Minimum two of the six courses; required path courses must be included.'} Selected: ${state.constrained.length} courses (${state.constrained.reduce((n,c)=>n+(R.map[c]?.ec||0),0)} EC).</p></section>`;
 sections+=`<section class="print-section"><h2>5. ${R.isEducation(state)?'Major research project':'Research projects and literature thesis'}</h2><h3>Major research project</h3>${printCourseTable(v.rows.filter(r=>r.section==='Major research project'))}<p>Registration route: ${R.isEducation(state)?'Fixed 30 EC Education major (XM_0200).':state.major.route==='split'?'18 EC Part 1 in 2026–2027 (XM_0207) + 30 EC Part 2 in 2027–2028 (to be announced).':state.major.route==='single'?'Single 48 EC course in 2027–2028 (to be announced).':'Not selected; the 48 EC are not counted.'}</p>${printProject('major','Major Research Project Details')}${state.student.path==='SMC'?'<p class="smc-reminder">For a Synthetic Radiopharmaceutical Chemistry internship, Advanced Radiopharmaceutical Chemistry is required preparation. Discuss this with the internship coordinator.</p>':''}${!R.isEducation(state)&&state.minor.enabled?`<h3>Minor research project</h3>${printCourseTable(v.rows.filter(r=>r.section==='Minor research project'))}${printProject('minor','Minor Research Project Details')}`:''}${!R.isEducation(state)&&state.literature.enabled?`<h3>Literature thesis</h3>${printCourseTable(v.rows.filter(r=>r.section==='Literature thesis'))}${printProject('literature','Literature thesis details')}`:''}</section>`;
 sections+=`<section class="print-section"><h2>6. Other elective courses</h2>${['General electives','Alpha/gamma electives','Education electives','Electives awaiting classification'].map(label=>{const rows=v.rows.filter(r=>r.section===label);return rows.length?`<h3>${R.isEducation(state)&&label==='General electives'?'DDS electives':label}${label==='Alpha/gamma electives'?' — maximum 18 EC':''}</h3>${printCourseTable(rows)}<p style="text-align:right"><strong>Subtotal: ${fmt(rows.reduce((a,r)=>a+r.ec,0))} EC</strong></p>`:''}).join('')}${R.isEducation(state)?`<h3>Component credit totals</h3><table class="print-table component-credit-table"><tbody><tr><td class="label">DDS component</td><td>${fmt(v.ddsTotal)} / 60 EC</td></tr><tr><td class="label">Education component</td><td>${fmt(v.educationTotal)} / 60 EC</td></tr></tbody></table><p>Alpha/gamma courses are not permitted in the DDS component. dr. Daan Geerke (d.p.geerke@vu.nl) preapproves both components.</p>`:''}<p class="print-total"><span class="total-label">Total credit count of PEP</span><strong>${fmt(v.total)} EC</strong></p></section>`;
 sections+=`<section class="print-section"><h2>7. Review and Generate PDF for approval</h2><p><strong>${esc(v.status)}</strong>. Automatic checks do not constitute preapproval or Examination Board approval.</p><table class="print-table print-check-table"><thead><tr><th>Check</th><th>Details</th><th>Status</th></tr></thead><tbody>${v.checks.map(c=>`<tr data-status="${c.status}"><td><strong class="check-title">${esc(c.label)}</strong><br><small>${esc(c.description)}</small></td><td>${esc(c.value)}</td><td class="check-status ${c.status}">${c.status==='pass'?'Passed':c.status==='review'?'Decision required':'Action needed'}</td></tr>`).join('')}</tbody></table>${v.issues.map(i=>`<div class="print-review-item" ${i.severity==='review'?`data-review-id="${esc(i.id)}"`: ''}>${i.severity==='review'?'<label class="print-review-checkbox"><input type="checkbox" aria-label="Reviewed"> Reviewed</label>':''}<strong>${i.severity==='error'?'ACTION NEEDED':i.severity==='review'?'DECISION / VERIFICATION REQUIRED':'PLANNING WARNING'}</strong><p class="${i.severity==='warning'||i.severity==='error'?'warning-text':''}">${esc(i.message)}</p>${i.requested?`<p class="exception-justification"><strong>Exception requested:</strong> ${esc(i.reason)}</p>${i.reference?`<p class="exception-justification">Supporting reference: ${esc(i.reference)}</p>`:''}`:''}</div>`).join('')}${state.notes?`<div class="print-review-item"><strong>Additional explanation (optional)</strong><p>${esc(state.notes)}</p></div>`:''}<p class="print-checks">${v.review.length?'Review checkboxes mean reviewed, not approved. Complete them before the coordinator signs. Exception requests still need the appropriate approval. ':''}Exemptions are requested separately; the exempted course remains included in this PEP.</p></section>`;
 sections+=`<section class="print-section print-approval"><h3>Signatures</h3><p class="print-checks">${v.principlesStatementRequired?'The Admissions Board completes its decision and signs first. The specialisation coordinator then signs the PEP.':'The specialisation coordinator completes the date and signs the PEP.'}</p><table class="print-table signature-table"><thead><tr>${v.principlesStatementRequired?'<th>Admissions Board for Principles courses</th>':''}<th>Specialisation coordinator preapproval for PEP</th></tr></thead><tbody><tr>${v.principlesStatementRequired?`<td><strong>Name:${requiredMark}</strong></td>`:''}<td><strong>Name:</strong> ${esc(R.coordinatorName(state))}</td></tr><tr>${v.principlesStatementRequired?`<td class="signature-space"><strong>Signature:${requiredMark}</strong></td>`:''}<td class="signature-space"><strong>Signature:${requiredMark}</strong></td></tr><tr>${v.principlesStatementRequired?`<td><strong>Date:${requiredMark}</strong></td>`:''}<td><strong>Date:${requiredMark}</strong></td></tr></tbody></table><p class="print-checks mandatory-note">* Mandatory for the relevant signatory. Use the downloaded PDF for digital signing.</p><p class="print-checks">Changes require renewed preapproval. Pending exception requests remain subject to a decision.</p></section>`;
 $('print-area').innerHTML=`<div class="print-head"><div><p>Master Drug Discovery Sciences</p><h1>Personal Education Plan Approval</h1>${resourceLinks()}</div><img src="${logo}" alt="Vrije Universiteit Amsterdam"></div>${draft?'<p class="print-watermark">DRAFT — NOT FOR SUBMISSION</p>':''}<p class="print-meta">Date generated: ${esc(time)}</p><div class="print-submission">${submissionInstructions()}</div>${sections}`;
 $('print-area').querySelectorAll('.print-section>h2').forEach((h,i)=>h.textContent=h.textContent.replace(/^\d+\. /,(i+1)+'. '));
 return v;
}
async function downloadPDF(){
 const snapshot=JSON.parse(JSON.stringify(state)),v=R.evaluate(snapshot);if(!v.canExport){toast('Complete the action-needed items or provide a permitted exception request first.');return;}
 const btn=$('download-pdf');btn.disabled=true;btn.textContent='Preparing PDF…';$('pdf-availability').textContent='Preparing your PDF…';
 try{preparePrint('review');const root=$('print-area').cloneNode(true);const name=filename();const bytes=await window.PEP_PDF.create(root,snapshot,logo);download(name+'.pdf',bytes,'application/pdf');toast('PDF downloaded. Send it to your specialisation coordinator for completion and preapproval.');}
 catch(e){toast('PDF download failed: '+e.message+' Export your draft to keep your entries and report the issue using the link at the bottom of the form.');}
 finally{btn.textContent='Download PDF for approval';update();}
}
$('main-content').addEventListener('input',inputted);$('main-content').addEventListener('change',changed);$('main-content').addEventListener('click',e=>{const button=e.target.closest('button');action(e);if(button?.dataset.action==='export-draft')saveDraft();if(button?.dataset.action==='open-draft')$('file-input').click();if(button?.id==='download-pdf')downloadPDF();});
$('save-draft').onclick=saveDraft;$('open-draft').onclick=()=>$('file-input').click();$('file-input').onchange=e=>openFile(e.target.files[0]);
$('review-button').onclick=()=>{$('review').scrollIntoView({behavior:'smooth'});$('review').setAttribute('tabindex','-1');$('review').focus({preventScroll:true});};
$('new-plan').onclick=()=>{if(confirm('Start a new PEP? Export your current draft first if you want to keep it.')){state=R.fresh();dirty=false;render();window.scrollTo(0,0);}};
window.addEventListener('beforeprint',()=>preparePrint('review'));
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
document.querySelector('.masthead h1').insertAdjacentHTML('afterend',resourceLinks());
$('form-version').textContent='Form version '+D.appVersion+' · '+D.releaseDate;
render();
const welcome=$('welcome-dialog'),welcomeKey='dds-pep-introduction-hidden';
function rememberWelcome(){try{if($('welcome-hide').checked)localStorage.setItem(welcomeKey,'yes');else localStorage.removeItem(welcomeKey);}catch(e){/* The introduction still works when browser storage is unavailable. */}}
$('welcome-hide').onchange=rememberWelcome;
$('welcome-close').onclick=()=>{rememberWelcome();welcome.close();};
$('welcome-start').onclick=()=>{rememberWelcome();welcome.close();$('student-firstName').focus({preventScroll:true});};
welcome.addEventListener('close',rememberWelcome);
$('getting-started').onclick=()=>welcome.showModal();
let hideWelcome=false;try{hideWelcome=localStorage.getItem(welcomeKey)==='yes';}catch(e){}
$('welcome-hide').checked=hideWelcome;if(!hideWelcome)welcome.showModal();
// Exposes the same deterministic functions for local automated verification; no network access.
window.PEP_APP={getState:()=>JSON.parse(JSON.stringify(state)),load:s=>{state=R.importDraft(s);dirty=false;render();},evaluate:()=>R.evaluate(state),preparePrint,downloadPDF};
})();
